import React from 'react';
import { useSkin } from '../middleware/SkinContext';


const DropPile = ({ onDropAction }) => {
  const { currentSkin } = useSkin();

  const handleDrop = (e) => {
    e.preventDefault();
    // Trigger the same logical action regardless of skin
    onDropAction();

    // Trigger the background flare effect
    const flare = new CustomEvent('bg-flare', { detail: { skin: currentSkin } });
    window.dispatchEvent(flare);
  };

  return (
    <div 
      className={`drop-pile ${currentSkin}-pile`}
      onDragOver={(e) => e.preventDefault()}
      onDrop={handleDrop}
    >
      <div className="pile-label">
        {currentSkin === 'futuristic' ? 'UPLINK DATA' : 'OFFER TO FORGE'}
      </div>
      <div className="pile-animation-core"></div>
    </div>
  );
};

import React, { createContext, useState, useContext, useEffect } from 'react';

const SkinContext = createContext();

export const SkinProvider = ({ children }) => {
  // Default skin is 'futuristic'
  const [currentSkin, setCurrentSkin] = useState('futuristic');

  // This effect updates the 'data-skin' attribute on the body tag
  // so your CSS can react to the change globally.
  useEffect(() => {
    document.body.setAttribute('data-skin', currentSkin);
  }, [currentSkin]);

  return (
    <SkinContext.Provider value={{ currentSkin, setCurrentSkin }}>
      {children}
    </SkinContext.Provider>
  );
};

export const useSkin = () => useContext(SkinContext);

